import{_ as o,c as t,o as a,ag as d}from"./chunks/framework.ymCRTBvy.js";const h=JSON.parse('{"title":"1.1_创建无Storyboard的Xcode项目","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/refactor/1.1_创建无Storyboard的Xcode项目.md","filePath":"uikit/refactor/1.1_创建无Storyboard的Xcode项目.md"}'),r={name:"uikit/refactor/1.1_创建无Storyboard的Xcode项目.md"};function c(i,e,n,l,s,p){return a(),t("div",null,e[0]||(e[0]=[d('<h1 id="_1-1-创建无storyboard的xcode项目" tabindex="-1">1.1_创建无Storyboard的Xcode项目 <a class="header-anchor" href="#_1-1-创建无storyboard的xcode项目" aria-label="Permalink to &quot;1.1_创建无Storyboard的Xcode项目&quot;">​</a></h1><h2 id="启动xcode并创建新项目" tabindex="-1">启动Xcode并创建新项目 <a class="header-anchor" href="#启动xcode并创建新项目" aria-label="Permalink to &quot;启动Xcode并创建新项目&quot;">​</a></h2><p>欢迎来到纯代码iOS开发的精彩世界！🚀 让我们从零开始，创建一个不依赖Storyboard的Xcode项目。这会让你对项目结构有更深入的理解，并为未来的组件化开发打下坚实基础。</p><p>首先，打开Xcode。在欢迎界面，你会看到“Create a new Xcode project”的选项。点击它，或者通过菜单栏选择 <code>File &gt; New &gt; Project</code>。</p><h2 id="选择项目模板" tabindex="-1">选择项目模板 <a class="header-anchor" href="#选择项目模板" aria-label="Permalink to &quot;选择项目模板&quot;">​</a></h2><p>在弹出的模板选择器中，你会看到各种项目类型。对于我们的纯代码项目，请选择 <code>iOS</code> 选项卡下的 <code>App</code> 模板。这个模板提供了一个最基础的iOS应用结构，非常适合我们进行手动配置。</p><p>点击 <code>Next</code> 继续。</p><h2 id="配置项目信息" tabindex="-1">配置项目信息 <a class="header-anchor" href="#配置项目信息" aria-label="Permalink to &quot;配置项目信息&quot;">​</a></h2><p>现在，你需要填写一些关键的项目信息。</p><ul><li><strong>Product Name (产品名称)</strong>: 这是你的应用名称。例如，你可以输入 <code>PureCodeApp</code>。</li><li><strong>Organization Identifier (组织标识符)</strong>: 通常是你的公司或个人域名的反向形式，例如 <code>com.yourcompany</code> 或 <code>com.yourname</code>。这与产品名称结合，形成应用的唯一Bundle Identifier。</li><li><strong>Interface (界面)</strong>: <strong>这是最关键的一步！</strong> 请务必从下拉菜单中选择 <code>Storyboard</code> 更改为 <code>SwiftUI</code>。等等，你可能会问，为什么是 <code>SwiftUI</code> 而不是 <code>UIKit</code>？这是因为选择 <code>SwiftUI</code> 模板时，Xcode默认不会生成 <code>Main.storyboard</code> 文件，这正是我们想要的！我们将在项目中手动配置UIKit。</li><li><strong>Language (语言)</strong>: 选择 <code>Swift</code>。</li><li><strong>Storage (存储)</strong>: 保持默认的 <code>None</code>。</li><li><strong>Include Tests (包含测试)</strong>: 暂时取消勾选，我们可以在后续需要时再添加。</li></ul><p>填写完毕后，点击 <code>Next</code>。</p><h2 id="选择项目存储位置" tabindex="-1">选择项目存储位置 <a class="header-anchor" href="#选择项目存储位置" aria-label="Permalink to &quot;选择项目存储位置&quot;">​</a></h2><p>Xcode会提示你选择一个位置来保存你的新项目。选择一个你喜欢的文件夹，然后点击 <code>Create</code>。恭喜你！🎉 一个全新的、没有Storyboard的Xcode项目已经成功创建了。你会发现项目导航器中没有 <code>Main.storyboard</code> 文件，这正是我们纯代码开发的起点。</p><h2 id="探索项目结构" tabindex="-1">探索项目结构 <a class="header-anchor" href="#探索项目结构" aria-label="Permalink to &quot;探索项目结构&quot;">​</a></h2><p>现在，花点时间熟悉一下新项目的结构。你会看到以下几个主要文件：</p><ul><li><code>AppDelegate.swift</code>: 这是应用的入口点，负责处理应用生命周期事件。</li><li><code>SceneDelegate.swift</code>: 在iOS 13及更高版本中，它负责管理应用的场景（或窗口）生命周期。</li><li><code>ContentView.swift</code>: 这是SwiftUI模板默认生成的一个视图文件，我们后续会将其替换为我们自己的UIKit视图。</li><li><code>Assets.xcassets</code>: 用于管理应用的图片资源。</li><li><code>Info.plist</code>: 包含应用配置信息的属性列表文件。</li></ul><p>通过这种方式创建项目，你将拥有对应用启动流程和视图层次结构更强的控制力。这为我们后续深入学习UIKit纯代码组件封装与重构技巧奠定了坚实的基础。你已经迈出了成功的第一步！💪</p>',17)]))}const u=o(r,[["render",c]]);export{h as __pageData,u as default};
